SELECT n.name, mi1.info, MIN(t.production_year), MAX(t.production_year) FROM title as t, kind_type as kt, movie_info as mi1, info_type as it1, cast_info as ci, role_type as rt, name as n WHERE t.id = ci.movie_id AND t.id = mi1.movie_id AND mi1.info_type_id = it1.id AND t.kind_id = kt.id AND ci.person_id = n.id AND ci.movie_id = mi1.movie_id AND ci.role_id = rt.id AND (it1.id IN ('3','5','8')) AND (mi1.info IN ('Finland:K-3','France:-18','France:12','France:Unrated','Greece:K','Hungary:16','Japan:PG12','Mexico:AA','Norway:A','Portugal:M/18','Singapore:(Banned)','South Africa:PG','Spain:7','West Germany:Not Rated','Yugoslavia')) AND (UPPER(n.name) LIKE UPPER('%sch%')) AND (kt.kind IN ('episode','movie','tv movie')) AND (rt.role IN ('actor','actress','cinematographer','costume designer')) GROUP BY HASH(SUBSTRING(mi1.info FROM 1 FOR 8000) || '#' || SUBSTRING(n.name FROM 1 FOR 8000)), 2, 1 
